/* ---- live ---- */
/* =========================================================
   Curaters – real-time information
   • Local time per destination (Intl, ticks every second, no network)
   • Weather, 7-day forecast, sunrise/sunset  → Open-Meteo (free, no key)
   • Exchange rates                           → open.er-api.com (free, no key)
   Everything degrades gracefully when offline.
   ========================================================= */
(function () {
  const C = (window.Curaters = window.Curaters || {});
  const L = (C.Live = {});

  /* ---------- units ---------- */
  let unit = 'C';
  try { unit = localStorage.getItem('curaters.unit') || 'C'; } catch (e) {}
  L.unit = () => unit;
  L.setUnit = (u) => { unit = u; try { localStorage.setItem('curaters.unit', u); } catch (e) {} document.dispatchEvent(new CustomEvent('curaters:unit')); };
  L.temp = (c) => (c == null || isNaN(c)) ? '–' : Math.round(unit === 'F' ? c * 9 / 5 + 32 : c) + '°';

  /* ---------- clocks ---------- */
  const fmtCache = {};
  function fmt(tz, opts) {
    const k = tz + JSON.stringify(opts);
    return fmtCache[k] || (fmtCache[k] = new Intl.DateTimeFormat('en-GB', Object.assign({ timeZone: tz }, opts)));
  }
  L.time = (tz, d) => fmt(tz, { hour: '2-digit', minute: '2-digit', hour12: false }).format(d || new Date());
  L.dayLabel = (tz, d) => fmt(tz, { weekday: 'short', day: 'numeric', month: 'short' }).format(d || new Date());
  L.offset = (tz, d) => {
    const p = fmt(tz, { timeZoneName: 'shortOffset' }).formatToParts(d || new Date()).find(x => x.type === 'timeZoneName');
    return p ? p.value.replace('GMT', 'UTC') : '';
  };
  L.hour = (tz, d) => parseInt(fmt(tz, { hour: '2-digit', hour12: false }).format(d || new Date()), 10) % 24;
  L.nowISO = (tz, d) => { // "YYYY-MM-DDTHH:mm" in the destination's zone
    const p = {}; fmt(tz, { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, hourCycle: 'h23' })
      .formatToParts(d || new Date()).forEach(x => { p[x.type] = x.value; });
    return p.year + '-' + p.month + '-' + p.day + 'T' + p.hour.replace('24', '00') + ':' + p.minute;
  };
  L.month = (tz, d) => parseInt(fmt(tz, { month: 'numeric' }).format(d || new Date()), 10);

  /** Keep every [data-clock] element ticking. */
  function tick() {
    const now = new Date();
    document.querySelectorAll('[data-clock]').forEach(el => {
      el.textContent = L.time(el.dataset.clock, now);
    });
    document.querySelectorAll('[data-clockday]').forEach(el => {
      el.textContent = L.dayLabel(el.dataset.clockday, now);
    });
  }
  L.startClocks = () => { tick(); if (!L._t) L._t = setInterval(tick, 1000); };

  /* ---------- weather ---------- */
  const WMO = {
    0: ['Clear sky', 'sun'], 1: ['Mostly clear', 'sun'], 2: ['Partly cloudy', 'partly'], 3: ['Overcast', 'cloud'],
    45: ['Fog', 'fog'], 48: ['Rime fog', 'fog'],
    51: ['Light drizzle', 'rain'], 53: ['Drizzle', 'rain'], 55: ['Heavy drizzle', 'rain'], 56: ['Freezing drizzle', 'rain'], 57: ['Freezing drizzle', 'rain'],
    61: ['Light rain', 'rain'], 63: ['Rain', 'rain'], 65: ['Heavy rain', 'rain'], 66: ['Freezing rain', 'rain'], 67: ['Freezing rain', 'rain'],
    71: ['Light snow', 'snow'], 73: ['Snow', 'snow'], 75: ['Heavy snow', 'snow'], 77: ['Snow grains', 'snow'],
    80: ['Showers', 'rain'], 81: ['Showers', 'rain'], 82: ['Violent showers', 'rain'], 85: ['Snow showers', 'snow'], 86: ['Snow showers', 'snow'],
    95: ['Thunderstorm', 'storm'], 96: ['Thunderstorm, hail', 'storm'], 99: ['Thunderstorm, hail', 'storm']
  };
  L.describe = (code, isDay) => {
    const w = WMO[code] || ['–', 'cloud'];
    let icon = w[1];
    if (isDay === 0 || isDay === false) { if (icon === 'sun') icon = 'moon'; if (icon === 'partly') icon = 'partly-night'; }
    return { label: w[0], icon };
  };

  const wcache = {}; // id -> {t, data}
  const WTTL = 10 * 60 * 1000;

  async function fetchWeather(list) {
    const lat = list.map(d => d.lat).join(','), lon = list.map(d => d.lon).join(',');
    const u = 'https://api.open-meteo.com/v1/forecast?latitude=' + lat + '&longitude=' + lon +
      '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,is_day,precipitation' +
      '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,sunrise,sunset,uv_index_max' +
      '&timezone=auto&forecast_days=7&wind_speed_unit=kmh';
    const ctl = new AbortController(); const to = setTimeout(() => ctl.abort(), 10000);
    try {
      const r = await fetch(u, { signal: ctl.signal });
      if (!r.ok) throw new Error('weather ' + r.status);
      const j = await r.json();
      return Array.isArray(j) ? j : [j];
    } finally { clearTimeout(to); }
  }

  /** Returns Promise<{[destId]: data|null}>; batches into one request. */
  L.weather = async function (dests) {
    const out = {}; const need = [];
    dests.forEach(d => {
      const c = wcache[d.id];
      if (c && Date.now() - c.t < WTTL) out[d.id] = c.data; else need.push(d);
    });
    if (need.length) {
      try {
        for (let i = 0; i < need.length; i += 25) {
          const chunk = need.slice(i, i + 25);
          const res = await fetchWeather(chunk);
          chunk.forEach((d, k) => { wcache[d.id] = { t: Date.now(), data: res[k] }; out[d.id] = res[k]; });
        }
      } catch (e) { need.forEach(d => { if (!(d.id in out)) out[d.id] = (wcache[d.id] && wcache[d.id].data) || null; }); }
    }
    return out;
  };

  /** Minutes until the next sunrise/sunset in the destination's zone. */
  L.sunInfo = (w, tz) => {
    if (!w || !w.daily) return null;
    const now = L.nowISO(tz);
    const day = now.slice(0, 10);
    const i = Math.max(0, w.daily.time.indexOf(day));
    const rise = w.daily.sunrise[i], set = w.daily.sunset[i];
    const toMs = (s) => Date.parse(s + ':00Z');
    const n = toMs(now);
    let next, kind;
    if (n < toMs(rise)) { next = rise; kind = 'Sunrise'; }
    else if (n < toMs(set)) { next = set; kind = 'Sunset'; }
    else { next = (w.daily.sunrise[i + 1] || rise); kind = 'Sunrise'; }
    const mins = Math.max(0, Math.round((toMs(next) - n) / 60000));
    return { rise: rise.slice(11), set: set.slice(11), kind, mins, next: next.slice(11) };
  };
  L.dur = (m) => (m >= 60 ? Math.floor(m / 60) + 'h ' + String(m % 60).padStart(2, '0') + 'm' : m + 'm');

  /* ---------- exchange rates ---------- */
  let rates = null;
  try { const c = JSON.parse(localStorage.getItem('curaters.fx')); if (c && Date.now() - c.t < 6 * 3600e3) rates = c; } catch (e) {}
  L.rates = async function () {
    if (rates) return rates;
    try {
      const r = await fetch('https://open.er-api.com/v6/latest/USD');
      if (!r.ok) throw new Error('fx');
      const j = await r.json();
      if (j.result !== 'success') throw new Error('fx');
      rates = { t: Date.now(), updated: j.time_last_update_utc, rates: j.rates };
      try { localStorage.setItem('curaters.fx', JSON.stringify(rates)); } catch (e) {}
    } catch (e) { rates = null; }
    return rates;
  };
  L.convert = (usd, cur) => {
    if (cur === 'USD' || !rates || !rates.rates[cur]) return { v: usd, cur: 'USD' };
    return { v: usd * rates.rates[cur], cur };
  };
  L.money = (usd, cur) => {
    const c = L.convert(usd, cur);
    try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: c.cur, maximumFractionDigits: 0 }).format(c.v); }
    catch (e) { return c.cur + ' ' + Math.round(c.v); }
  };

  /* ---------- weather icons (SVG sprite) ---------- */
  L.sprite = '<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>' +
    '<symbol id="i-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M18.7 5.3l-1.6 1.6M6.9 17.1l-1.6 1.6"/></symbol>' +
    '<symbol id="i-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></symbol>' +
    '<symbol id="i-cloud" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M7 18.5h10a4 4 0 0 0 .6-7.95A5.5 5.5 0 0 0 7.1 9.6 4.5 4.5 0 0 0 7 18.5z"/></symbol>' +
    '<symbol id="i-partly" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v1.6M4.6 6.6l1.1 1.1M3 13h1.6M19.4 6.6l-1.1 1.1"/><path d="M8.2 11.2A4 4 0 0 1 15.6 9"/><path d="M8 19h9a3.5 3.5 0 0 0 .5-6.96A4.8 4.8 0 0 0 8.4 12 3.5 3.5 0 0 0 8 19z"/></symbol>' +
    '<symbol id="i-partly-night" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M10 4.2a5 5 0 1 0 7.3 6"/><path d="M8 19h9a3.5 3.5 0 0 0 .5-6.96A4.8 4.8 0 0 0 8.4 12 3.5 3.5 0 0 0 8 19z"/></symbol>' +
    '<symbol id="i-fog" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M4 9h16M3 13h18M6 17h12"/></symbol>' +
    '<symbol id="i-rain" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M7 15h10a4 4 0 0 0 .6-7.95A5.5 5.5 0 0 0 7.1 6.1 4.5 4.5 0 0 0 7 15z"/><path d="M8 18l-1 2.5M12 18l-1 2.5M16 18l-1 2.5"/></symbol>' +
    '<symbol id="i-storm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M7 14.5h10a4 4 0 0 0 .6-7.95A5.5 5.5 0 0 0 7.1 5.6 4.5 4.5 0 0 0 7 14.5z"/><path d="M12.5 14l-2 3.5h3l-2 3.5"/></symbol>' +
    '<symbol id="i-snow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M12 3v18M4.2 7.5l15.6 9M19.8 7.5l-15.6 9"/></symbol>' +
    '<symbol id="i-pin" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s7-5.6 7-11a7 7 0 0 0-14 0c0 5.4 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/></symbol>' +
    '<symbol id="i-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></symbol>' +
    '<symbol id="i-x" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></symbol>' +
    '<symbol id="i-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5l7 7-7 7"/></symbol>' +
    '<symbol id="i-clock" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></symbol>' +
    '<symbol id="i-search" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"/><path d="M20 20l-4-4"/></symbol>' +
    '<symbol id="i-sunrise" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v4M7 9l-1.5-1.5M17 9l1.5-1.5M3 17h18M7 17a5 5 0 0 1 10 0M8 21h8"/></symbol>' +
    '</defs></svg>';
  L.icon = (name, cls) => '<svg class="ico ' + (cls || '') + '" aria-hidden="true"><use href="#i-' + name + '"/></svg>';
})();

/* ---- photos ---- */
/* =========================================================
   Curaters – real destination photography
   ---------------------------------------------------------
   Every destination is matched to genuine photographs of that exact
   place from Wikimedia Commons (free-licensed). Photos are discovered
   from the destination's own Wikipedia article(s), checked against the
   Commons API (real JPEG, high resolution, landscape, free licence),
   de-duplicated so one photo is never reused for another destination,
   and served in optimised sizes (500 / 960 / 1280 / 1920 px wide).
   The photographer + licence are kept for on-page credits.

   If the network is unavailable, a tasteful gradient placeholder is shown.
   To self-host the photos instead, run:  node tools/fetch-images.mjs
   ========================================================= */
(function () {
  const C = (window.Curaters = window.Curaters || {});
  const TTL = 7 * 24 * 3600 * 1000;
  const KEY = 'curaters.photos.v3';
  const SIZES = [500, 960, 1280, 1920];
  const BAD = /map|flag|locator|location|coat[ _]of|logo|icon|diagram|chart|symbol|seal|emblem|stub|stamp|banknote|sketch|drawing|engraving|painting|illustration|lithograph|print|postcard|commons-|wikidata|ambox|portrait|coin|poster|plan[ _]of|scheme|route|timeline|satellite/i;

  const store = read();
  const claimed = new Map();   // file name -> destination id (de-duplication)
  const inflight = new Map();  // destination id -> Promise
  const used = new Map();      // file name -> item (for the credits dialog)

  function read() {
    try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch (e) { return {}; }
  }
  function write() {
    try { localStorage.setItem(KEY, JSON.stringify(store)); } catch (e) { /* storage full / blocked */ }
  }

  async function getJSON(url, ms) {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), ms || 9000);
    try {
      const r = await fetch(url, { signal: ctl.signal, headers: { Accept: 'application/json' } });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } finally { clearTimeout(t); }
  }

  const strip = (html) => {
    if (!html) return '';
    const d = new DOMParser().parseFromString(String(html), 'text/html');
    return (d.body.textContent || '').replace(/\s+/g, ' ').trim();
  };

  async function articleFiles(article) {
    try {
      const j = await getJSON('https://en.wikipedia.org/api/rest_v1/page/media-list/' + encodeURIComponent(article));
      return (j.items || []).filter(i => i.type === 'image' && i.title).map(i => i.title);
    } catch (e) {
      try { // fallback: classic MediaWiki API
        const u = 'https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=images&imlimit=60&redirects=1&titles=' + encodeURIComponent(article);
        const j = await getJSON(u);
        const p = Object.values((j.query && j.query.pages) || {})[0];
        return ((p && p.images) || []).map(i => i.title);
      } catch (e2) { return []; }
    }
  }

  async function commonsInfo(titles) {
    const out = [];
    for (let i = 0; i < titles.length; i += 20) {
      const chunk = titles.slice(i, i + 20);
      const u = 'https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&prop=imageinfo' +
        '&iiprop=size|mime|extmetadata&iiextmetadatafilter=Artist|LicenseShortName|LicenseUrl|ImageDescription' +
        '&titles=' + encodeURIComponent(chunk.join('|'));
      try {
        const j = await getJSON(u);
        Object.values((j.query && j.query.pages) || {}).forEach(p => {
          const ii = p.imageinfo && p.imageinfo[0];
          if (!ii) return;
          const m = ii.extmetadata || {};
          out.push({
            title: p.title,
            name: p.title.replace(/^File:/, ''),
            w: ii.width, h: ii.height, mime: ii.mime,
            artist: strip(m.Artist && m.Artist.value).slice(0, 70),
            license: strip(m.LicenseShortName && m.LicenseShortName.value),
            licenseUrl: m.LicenseUrl && m.LicenseUrl.value,
            alt: strip(m.ImageDescription && m.ImageDescription.value).slice(0, 160)
          });
        });
      } catch (e) { /* skip chunk */ }
    }
    return out;
  }

  async function resolve(dest) {
    let titles = (dest.files || []).map(f => 'File:' + f);
    // The article's lead image is, by definition, the representative photo of the place: put it first.
    const leads = await Promise.all((dest.wiki || []).slice(0, 1).map(async a => {
      try { const j = await getJSON('https://en.wikipedia.org/api/rest_v1/page/summary/' + encodeURIComponent(a));
        const u = j.originalimage && j.originalimage.source; if (!u) return null;
        return 'File:' + decodeURIComponent(u.split('/').pop()); } catch (e) { return null; }
    }));
    titles = leads.filter(Boolean).concat(titles);
    const lists = await Promise.all((dest.wiki || []).map(articleFiles));
    lists.forEach(l => { titles = titles.concat(l); });
    const seen = new Set();
    titles = titles.map(t => t.replace(/_/g, ' ')).filter(t => {
      if (seen.has(t)) return false; seen.add(t);
      return /\.jpe?g$/i.test(t) && !BAD.test(t);
    }).slice(0, 40);
    if (!titles.length) return [];
    const info = await commonsInfo(titles);
    const order = new Map(titles.map((t, i) => [t, i]));
    return info
      .filter(i => i.mime === 'image/jpeg' && i.w >= 1500 && i.h >= 900 && i.w / i.h >= 1.25 && i.w / i.h <= 2.6 &&
        !/fair use|non-free|all rights/i.test(i.license || ''))
      .sort((a, b) => order.get(a.title) - order.get(b.title))
      .map(i => ({ ...i, page: 'https://commons.wikimedia.org/wiki/' + encodeURI(i.title.replace(/ /g, '_')) }));
  }

  /** Resolve (and cache) the photo list of a destination. */
  function get(dest) {
    const local = (dest.local || []).map(src => ({ local: true, src, name: dest.name, artist: 'Curaters', license: '' }));
    const hit = store[dest.id];
    if (hit && Date.now() - hit.t < TTL && hit.items.length) return Promise.resolve(finish(dest, local, hit.items));
    if (inflight.has(dest.id)) return inflight.get(dest.id);
    const p = resolve(dest).then(items => {
      if (items.length) { store[dest.id] = { t: Date.now(), items: items.slice(0, 14) }; write(); }
      return finish(dest, local, items);
    }).catch(() => finish(dest, local, [])).finally(() => inflight.delete(dest.id));
    inflight.set(dest.id, p);
    return p;
  }

  function finish(dest, local, remote) {
    const items = [];
    remote.forEach(it => {
      const owner = claimed.get(it.name);
      if (owner && owner !== dest.id) return;       // never reuse a photo across destinations
      claimed.set(it.name, dest.id);
      items.push(it);
    });
    const all = local.concat(items.slice(0, 12));
    all.forEach(it => { if (!it.local) used.set(it.name, it); });
    return all;
  }

  const width = (item, w) => 'https://commons.wikimedia.org/wiki/Special:FilePath/' + encodeURIComponent(item.name) + '?width=' + w;
  const url = (item, w) => item.local ? item.src : width(item, w || 1280);
  const srcset = (item) => item.local ? '' : SIZES.filter(s => s <= Math.max(500, item.w)).map(s => width(item, s) + ' ' + s + 'w').join(', ');
  const credit = (item) => item.local ? '' :
    'Photo: ' + (item.artist || 'Wikimedia Commons contributor') + (item.license ? ' · ' + item.license : '') + ' · Wikimedia Commons';

  function setImage(img, item, sizes, w) {
    img.alt = img.alt || (item.alt || item.name || '');
    if (sizes) img.sizes = sizes;
    if (!item.local) img.srcset = srcset(item);
    img.src = url(item, w || 960);
  }

  /**
   * Fill a .ph wrapper (containing an <img>) with the destination's photo.
   * opts: { index, sizes, onItem }
   */
  function fill(ph, dest, opts) {
    opts = opts || {};
    const img = ph.querySelector('img');
    ph.classList.add('is-loading');
    return get(dest).then(items => {
      const item = items[opts.index || 0] || items[0];
      if (!item) { ph.classList.remove('is-loading'); ph.classList.add('is-fallback'); return null; }
      img.addEventListener('load', () => { ph.classList.remove('is-loading'); ph.classList.add('is-ready'); }, { once: true });
      img.addEventListener('error', () => { ph.classList.remove('is-loading'); ph.classList.add('is-fallback'); }, { once: true });
      img.alt = dest.name + ', ' + dest.country;
      setImage(img, item, opts.sizes || '(max-width:640px) 100vw, (max-width:1100px) 50vw, 33vw', opts.w);
      if (img.complete && img.naturalWidth) { ph.classList.remove('is-loading'); ph.classList.add('is-ready'); }
      if (opts.onItem) opts.onItem(item, items);
      return item;
    });
  }

  /** Lazy variant: load when the element approaches the viewport. */
  const io = 'IntersectionObserver' in window ? new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (!e.isIntersecting) return;
      io.unobserve(e.target);
      const d = e.target.__dest; if (d) fill(e.target, d, e.target.__opts);
    });
  }, { rootMargin: '400px 0px' }) : null;

  function lazy(ph, dest, opts) {
    ph.__dest = dest; ph.__opts = opts;
    ph.classList.add('is-loading');
    if (io) io.observe(ph); else fill(ph, dest, opts);
  }

  C.Photos = { get, fill, lazy, url, srcset, credit, width, credits: () => Array.from(used.values()) };
})();

/* ---- app ---- */
/* =========================================================
   Curaters – shared UI (header, footer, cards, dialogs, helpers)
   ========================================================= */
(function () {
  const C = (window.Curaters = window.Curaters || {});
  const L = C.Live, P = C.Photos;
  const UI = (C.UI = {}); C.route = C.route || { name: 'home', search: '' };
  const $ = (s, r) => (r || document).querySelector(s);
  const $$ = (s, r) => Array.from((r || document).querySelectorAll(s));
  UI.$ = $; UI.$$ = $$;

  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const RATE = ['Off-season', 'Fair', 'Good', 'Prime'];
  UI.MONTHS = MONTHS; UI.RATE = RATE;
  UI.esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  UI.param = (k) => new URLSearchParams(Curaters.route.search).get(k);
  UI.dest = (id) => C.DESTINATIONS.find(d => d.id === id);
  UI.rating = (d, m) => Number(d.months[(m || (new Date().getMonth() + 1)) - 1]);
  const reduceMotion = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const canHover = window.matchMedia && matchMedia('(hover: hover) and (pointer: fine)').matches;
  UI.reduceMotion = reduceMotion;

  /* ---------- wishlist ("My trip") ---------- */
  const WK = 'curaters.wish';
  const wish = { list() { try { return JSON.parse(localStorage.getItem(WK)) || []; } catch (e) { return []; } },
    has(id) { return this.list().includes(id); },
    toggle(id) { let l = this.list(); const on = !l.includes(id); l = on ? l.concat(id) : l.filter(x => x !== id);
      try { localStorage.setItem(WK, JSON.stringify(l)); } catch (e) {}
      document.dispatchEvent(new CustomEvent('curaters:wish', { detail: { id, on } })); return on; },
    set(l) { try { localStorage.setItem(WK, JSON.stringify(l)); } catch (e) {} document.dispatchEvent(new CustomEvent('curaters:wish')); } };
  C.Wish = wish;

  /* ---------- toast ---------- */
  UI.toast = function (msg) {
    let t = $('#toast');
    if (!t) { t = document.createElement('div'); t.id = 'toast'; t.className = 'toast'; t.setAttribute('role', 'status'); document.body.appendChild(t); }
    t.textContent = msg; t.classList.add('on');
    clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('on'), 2600);
  };

  /* ---------- header & footer ---------- */
  function header() {
    const page = document.body.dataset.page || '';
    const link = (href, label, key) => '<a href="' + href + '"' + (page === key ? ' aria-current="page"' : '') + '>' + label + '</a>';
    const nav = link('#/destinations', 'Destinations', 'destinations') + link('#/trips', 'Trips', 'trips') +
      link('#/plan', 'Plan a trip', 'plan') + link('#/about', 'About', 'about');
    const h = document.createElement('header');
    h.className = 'site-header'; h.id = 'siteHeader';
    h.innerHTML =
      '<div class="container hdr">' +
      '<a class="brand" href="#/" aria-label="Curaters home"><img class="logo-light" src="' + C.ASSETS['wordmark-light'] + '" alt="Curaters" width="150" height="27"><img class="logo-dark" src="' + C.ASSETS['wordmark-dark'] + '" alt="" width="150" height="27"></a>' +
      '<nav class="nav" aria-label="Main">' + nav + '</nav>' +
      '<div class="hdr-tools">' +
      '<button class="unit" type="button" aria-label="Switch temperature unit" title="Switch temperature unit"><span data-u="C">°C</span><i>/</i><span data-u="F">°F</span></button>' +
      '<a class="trip-pill" href="#/plan" aria-label="My trip"><svg class="ico"><use href="#i-pin"/></svg><span>My trip</span><b class="count" data-wishcount>0</b></a>' +
      '<a class="btn btn-primary btn-sm hide-sm" href="#/plan">Request a trip</a>' +
      '<button class="burger" type="button" aria-label="Open menu" aria-expanded="false" aria-controls="mnav"><span></span><span></span></button>' +
      '</div></div>' +
      '<div class="mnav" id="mnav" hidden><nav aria-label="Mobile">' + nav + '<a class="btn btn-primary" href="#/plan">Request a trip</a></nav></div>';
    return h;
  }

  function footer() {
    const f = document.createElement('footer');
    f.className = 'site-footer';
    f.innerHTML =
      '<div class="container"><div class="foot-card">' +
      '<div class="foot-top"><div class="foot-brand">' +
      '<div class="foot-logo"><img src="' + C.ASSETS['wordmark-light'] + '" alt="Curaters" width="170" height="30"></div>' +
      '<p class="eyebrow">Curated African travel experiences</p>' +
      '<p class="foot-vision">Our vision is to turn travel into art: carefully curated, deeply felt, and impossible to forget.</p>' +
      '<div class="foot-contact"><p class="eyebrow">Email</p><a href="mailto:' + C.CONTACT.email + '">' + C.CONTACT.email + '</a></div></div>' +
      '<div class="foot-links"><div><h3>Explore</h3><ul>' +
      '<li><a href="#/destinations">Destinations</a></li><li><a href="#/trips">Trips</a></li><li><a href="#/plan">Plan a trip</a></li><li><a href="#/trips?type=private">Private trips</a></li></ul></div>' +
      '<div><h3>Company</h3><ul><li><a href="#/about">Why Curaters</a></li><li><a href="#/about">FAQ</a></li><li><a href="#/plan">Contact</a></li></ul></div></div></div>' +
      '<div class="foot-line"></div>' +
      '<div class="foot-bottom"><div class="socials">' +
      '<a class="social" href="' + C.CONTACT.instagram + '" target="_blank" rel="noopener noreferrer"><svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="3" width="18" height="18" rx="5" stroke-width="2"/><circle cx="12" cy="12" r="4" stroke-width="2"/><circle cx="17" cy="7" r="1.5" fill="currentColor"/></svg><span>Instagram</span></a>' +
      '<a class="social" href="' + C.CONTACT.tiktok + '" target="_blank" rel="noopener noreferrer"><svg class="ico" viewBox="0 0 24 24" fill="currentColor"><path d="M9 3v12.5a3.5 3.5 0 1 1-2.5-3.35V9.5a7 7 0 1 0 5 6.7V7.5c1.3 1.2 3 2 4.5 2.1V6.5c-1.6-.2-3.5-1.2-4.5-2.5H9z"/></svg><span>TikTok</span></a></div>' +
      '<div class="foot-legal"><p>© Curaters ' + new Date().getFullYear() + '</p>' +
      '<button type="button" class="link-btn" data-credits>Photo credits</button>' +
      '<a href="#/about">Terms and Conditions</a><a href="#/about">Privacy Policy</a></div></div>' +
      '<p class="foot-live"><span class="dot"></span> Local times, weather and exchange rates on this site update live.</p>' +
      '</div></div>';
    return f;
  }

  function wireHeader(h) {
    const burger = $('.burger', h), mnav = $('#mnav', h);
    const close = () => { burger.setAttribute('aria-expanded', 'false'); mnav.hidden = true; document.body.classList.remove('menu-open'); };
    burger.addEventListener('click', () => {
      const open = burger.getAttribute('aria-expanded') !== 'true';
      burger.setAttribute('aria-expanded', String(open)); mnav.hidden = !open; document.body.classList.toggle('menu-open', open);
    });
    $$('a', mnav).forEach(a => a.addEventListener('click', close));
    document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    window.addEventListener('resize', () => { if (innerWidth > 900) close(); });

    const onScroll = () => {
      h.classList.toggle('is-solid', document.body.dataset.header !== 'overlay' || scrollY > 40);
      const st = document.documentElement; const max = st.scrollHeight - innerHeight;
      document.documentElement.style.setProperty('--progress', max > 0 ? (scrollY / max).toFixed(4) : 0);
      const bt = $('#toTop'); if (bt) bt.classList.toggle('on', scrollY > 900);
      const sc = $('#stickyCta'); if (sc) sc.classList.toggle('on', scrollY > 600);
    };
    onScroll(); addEventListener('scroll', onScroll, { passive: true });

    const syncUnit = () => $$('.unit [data-u]', h).forEach(s => s.classList.toggle('on', s.dataset.u === L.unit()));
    syncUnit(); document.addEventListener('curaters:unit', syncUnit);
    $('.unit', h).addEventListener('click', () => L.setUnit(L.unit() === 'C' ? 'F' : 'C'));

    const syncCount = () => { const n = wish.list().length; $$('[data-wishcount]').forEach(b => { b.textContent = n; b.hidden = !n; }); };
    syncCount(); document.addEventListener('curaters:wish', syncCount);
  }

  /* ---------- reveal on scroll ---------- */
  UI.reveal = function (root) {
    const els = $$('.reveal:not(.in)', root);
    if (!('IntersectionObserver' in window) || reduceMotion) { els.forEach(e => e.classList.add('in')); return; }
    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), { threshold: .12, rootMargin: '0px 0px -40px 0px' });
    els.forEach((e, i) => { e.style.setProperty('--d', ((i % 6) * 70) + 'ms'); io.observe(e); });
  };

  /* ---------- magnetic buttons + card tilt (pointer devices only) ---------- */
  function pointerFx() {
    if (!canHover || reduceMotion) return;
    document.addEventListener('pointermove', e => {
      const m = e.target.closest && e.target.closest('.magnetic');
      if (m) { const r = m.getBoundingClientRect(); m.style.transform = 'translate(' + ((e.clientX - r.left - r.width / 2) * .18).toFixed(1) + 'px,' + ((e.clientY - r.top - r.height / 2) * .28).toFixed(1) + 'px)'; }
      const c = e.target.closest && e.target.closest('.tilt');
      if (c) { const r = c.getBoundingClientRect(); const x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
        c.style.setProperty('--rx', ((.5 - y) * 6).toFixed(2) + 'deg'); c.style.setProperty('--ry', ((x - .5) * 8).toFixed(2) + 'deg');
        c.style.setProperty('--mx', (x * 100).toFixed(1) + '%'); c.style.setProperty('--my', (y * 100).toFixed(1) + '%'); }
    }, { passive: true });
    document.addEventListener('pointerout', e => {
      const m = e.target.closest && e.target.closest('.magnetic'); if (m && !m.contains(e.relatedTarget)) m.style.transform = '';
      const c = e.target.closest && e.target.closest('.tilt'); if (c && !c.contains(e.relatedTarget)) { c.style.setProperty('--rx', '0deg'); c.style.setProperty('--ry', '0deg'); }
    });
  }

  /* ---------- month bars ---------- */
  UI.monthBars = function (d, hl) {
    const r = d.months.split('').map(Number);
    return '<div class="mbars" role="img" aria-label="Best time to visit ' + UI.esc(d.name) + ' by month">' +
      r.map((v, i) => '<div class="mb' + (i + 1 === hl ? ' is-now' : '') + '" data-r="' + v + '" title="' + MONTHS[i] + ': ' + RATE[v] + '"><span style="--h:' + [10, 36, 66, 100][v] + '%"></span><em>' + MONTHS[i][0] + '</em></div>').join('') + '</div>';
  };

  /* ---------- live weather helpers ---------- */
  UI.chip = (w) => {
    if (!w || !w.current) return '<span class="muted">Live weather…</span>';
    const k = L.describe(w.current.weather_code, w.current.is_day);
    return L.icon(k.icon) + '<b>' + L.temp(w.current.temperature_2m) + '</b>';
  };

  UI.hydrateWeather = async function (root) {
    const els = $$('[data-w]', root);
    if (!els.length) return;
    const ids = Array.from(new Set(els.map(e => e.dataset.w)));
    const w = await L.weather(ids.map(UI.dest));
    els.forEach(e => { e.innerHTML = UI.chip(w[e.dataset.w]); e.classList.toggle('is-live', !!w[e.dataset.w]); });
  };

  UI.forecast = (w, tz, n) => {
    if (!w || !w.daily) return '';
    const today = L.nowISO(tz).slice(0, 10);
    let i0 = Math.max(0, w.daily.time.indexOf(today));
    const out = [];
    for (let i = i0; i < Math.min(w.daily.time.length, i0 + (n || 7)); i++) {
      const dt = new Date(w.daily.time[i] + 'T12:00:00Z');
      const k = L.describe(w.daily.weather_code[i], 1);
      out.push('<li><span class="fc-d">' + (i === i0 ? 'Today' : dt.toLocaleDateString('en-GB', { weekday: 'short', timeZone: 'UTC' })) + '</span>' + L.icon(k.icon) +
        '<b>' + L.temp(w.daily.temperature_2m_max[i]) + '</b><span class="fc-lo">' + L.temp(w.daily.temperature_2m_min[i]) + '</span>' +
        '<span class="fc-p" title="Chance of precipitation">' + (w.daily.precipitation_probability_max[i] ?? 0) + '%</span></li>');
    }
    return '<ul class="forecast">' + out.join('') + '</ul>';
  };

  UI.liveFull = function (d, w, fx) {
    const cur = w && w.current; const k = cur ? L.describe(cur.weather_code, cur.is_day) : null;
    const sun = L.sunInfo(w, d.tz);
    const rate = fx && fx.rates && fx.rates[d.currency];
    return '<div class="live-grid">' +
      '<div class="live-cell"><p class="eyebrow">Local time</p><p class="live-big"><span data-clock="' + d.tz + '">' + L.time(d.tz) + '</span></p><p class="muted"><span data-clockday="' + d.tz + '">' + L.dayLabel(d.tz) + '</span> · ' + L.offset(d.tz) + '</p></div>' +
      '<div class="live-cell"><p class="eyebrow">Right now</p>' + (cur ?
        '<p class="live-big">' + L.icon(k.icon, 'ico-lg') + ' ' + L.temp(cur.temperature_2m) + '</p><p class="muted">' + k.label + ' · feels ' + L.temp(cur.apparent_temperature) + '</p>' :
        '<p class="live-big">–</p><p class="muted">Weather unavailable offline</p>') + '</div>' +
      '<div class="live-cell"><p class="eyebrow">' + (sun ? sun.kind : 'Sun') + '</p>' + (sun ?
        '<p class="live-big">' + sun.next + '</p><p class="muted">in ' + L.dur(sun.mins) + ' · ☀ ' + sun.rise + ' / ' + sun.set + '</p>' : '<p class="live-big">–</p><p class="muted">&nbsp;</p>') + '</div>' +
      '<div class="live-cell"><p class="eyebrow">Currency</p>' + (rate ?
        '<p class="live-big">' + d.currency + '</p><p class="muted">1 USD ≈ ' + (rate >= 100 ? Math.round(rate).toLocaleString('en-US') : rate.toFixed(2)) + ' ' + d.currency + '</p>' :
        '<p class="live-big">' + d.currency + '</p><p class="muted">Rates unavailable offline</p>') + '</div></div>' +
      (cur ? '<p class="live-extra muted">Humidity ' + Math.round(cur.relative_humidity_2m) + '% · Wind ' + Math.round(cur.wind_speed_10m) + ' km/h' + (w.daily.uv_index_max && w.daily.uv_index_max[0] != null ? ' · UV max ' + Math.round(w.daily.uv_index_max[0]) : '') + '</p>' : '');
  };

  /* ---------- destination card ---------- */
  UI.destCard = function (d, opts) {
    opts = opts || {};
    const el = document.createElement('article');
    el.className = 'dcard tilt reveal' + (opts.cls ? ' ' + opts.cls : '');
    el.dataset.id = d.id; el.style.setProperty('--hue', d.hue);
    const nowR = UI.rating(d);
    const themeNames = d.tags.map(t => (C.THEMES.find(x => x.id === t) || {}).label).filter(Boolean);
    el.innerHTML =
      '<a class="dcard-link" href="#/destination?d=' + d.id + '" aria-label="' + UI.esc(d.name + ', ' + d.country) + '">' +
      '<div class="ph"><img decoding="async" loading="lazy" alt=""><div class="ph-fb" aria-hidden="true"><span>' + UI.esc(d.name) + '</span></div></div>' +
      '<div class="dcard-shade"></div><div class="dcard-glow"></div>' +
      '<div class="dcard-top"><span class="pill">' + UI.esc(d.country) + '</span><span class="pill live" data-w="' + d.id + '">' + UI.chip(null) + '</span></div>' +
      '<div class="dcard-body"><p class="eyebrow">' + UI.esc(d.region) + '</p><h3>' + UI.esc(d.name) + '</h3><p class="dcard-tag">' + UI.esc(d.tagline) + '</p>' +
      '<div class="dcard-more"><div class="dcard-more-in"><p class="dcard-desc">' + UI.esc(d.desc) + '</p>' +
      '<div class="dcard-meta"><span>' + L.icon('clock') + '<b data-clock="' + d.tz + '">' + L.time(d.tz) + '</b> local</span><span class="season s' + nowR + '">' + RATE[nowR] + ' this month</span></div>' +
      '<p class="dcard-themes">' + themeNames.join(' · ') + '</p>' +
      '<span class="dcard-cta">Explore ' + L.icon('arrow') + '</span></div></div></div></a>' +
      '<button class="dcard-save" type="button" aria-pressed="' + wish.has(d.id) + '" aria-label="Add ' + UI.esc(d.name) + ' to my trip" title="Add to my trip"><svg class="ico" viewBox="0 0 24 24"><path d="M12 20.5s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 7.8a4.3 4.3 0 0 1 7.5 2.5c0 5.6-7.5 10.2-7.5 10.2z"/></svg></button>' +
      '<button class="dcard-quick" type="button">Quick look</button>';
    P.lazy($('.ph', el), d, { sizes: '(max-width:640px) 100vw, (max-width:1100px) 50vw, 33vw' });
    const save = $('.dcard-save', el);
    save.addEventListener('click', e => { e.preventDefault(); const on = wish.toggle(d.id); UI.toast(on ? d.name + ' added to your trip' : d.name + ' removed'); });
    document.addEventListener('curaters:wish', () => save.setAttribute('aria-pressed', String(wish.has(d.id))));
    $('.dcard-quick', el).addEventListener('click', e => { e.preventDefault(); UI.quickLook(d); });
    return el;
  };

  /* ---------- dialogs ---------- */
  function dialog(cls) {
    const dlg = document.createElement('dialog'); dlg.className = 'dlg ' + (cls || '');
    document.body.appendChild(dlg);
    dlg.addEventListener('click', e => { if (e.target === dlg) dlg.close(); });
    dlg.addEventListener('close', () => { document.body.classList.remove('dlg-open'); setTimeout(() => dlg.remove(), 200); });
    return dlg;
  }
  UI.dialog = dialog;
  const openDlg = (dlg) => { if (dlg.showModal) dlg.showModal(); else dlg.setAttribute('open', ''); document.body.classList.add('dlg-open'); };

  UI.quickLook = function (d) {
    const dlg = dialog('ql');
    dlg.style.setProperty('--hue', d.hue);
    dlg.innerHTML =
      '<button class="dlg-x" type="button" aria-label="Close"><svg class="ico"><use href="#i-x"/></svg></button>' +
      '<div class="ql-media"><div class="ph"><img decoding="async" alt=""><div class="ph-fb"><span>' + UI.esc(d.name) + '</span></div></div><p class="credit" data-credit></p></div>' +
      '<div class="ql-body"><p class="eyebrow">' + UI.esc(d.region + ' · ' + d.country) + '</p><h2>' + UI.esc(d.name) + '</h2><p class="lead">' + UI.esc(d.tagline) + '</p><p>' + UI.esc(d.desc) + '</p>' +
      '<div class="ql-live" data-live><p class="muted">Loading live conditions…</p></div>' +
      '<p class="eyebrow">Best time to go</p>' + UI.monthBars(d, new Date().getMonth() + 1) +
      '<div class="ql-actions"><a class="btn btn-primary" href="#/destination?d=' + d.id + '">Full destination guide ' + L.icon('arrow') + '</a>' +
      '<button class="btn btn-ghost" type="button" data-wish aria-pressed="' + wish.has(d.id) + '"><span class="on-t">Added to my trip</span><span class="off-t">Add to my trip</span></button></div></div>';
    openDlg(dlg);
    $('.dlg-x', dlg).addEventListener('click', () => dlg.close());
    $('[data-wish]', dlg).addEventListener('click', e => { const on = wish.toggle(d.id); e.currentTarget.setAttribute('aria-pressed', String(on)); });
    P.fill($('.ph', dlg), d, { sizes: '(max-width:800px) 100vw, 50vw', onItem: it => { $('[data-credit]', dlg).textContent = P.credit(it); } });
    Promise.all([L.weather([d]), L.rates()]).then(([w, fx]) => { if (dlg.isConnected) { $('[data-live]', dlg).innerHTML = UI.liveFull(d, w[d.id], fx); L.startClocks(); } });
  };

  UI.creditsDialog = function () {
    const items = P.credits();
    const dlg = dialog('credits');
    dlg.innerHTML = '<button class="dlg-x" type="button" aria-label="Close"><svg class="ico"><use href="#i-x"/></svg></button><div class="dlg-pad"><h2>Photo credits</h2>' +
      '<p class="muted">Destination photographs are free-licensed images from Wikimedia Commons, matched to the real place they show. Click a title for the original file and full licence.</p>' +
      (items.length ? '<ul class="credit-list">' + items.map(i => '<li><a href="' + UI.esc(i.page) + '" target="_blank" rel="noopener noreferrer">' + UI.esc(i.name.replace(/\.[a-z]+$/i, '')) + '</a><span>' + UI.esc((i.artist || 'Unknown author') + (i.license ? ' · ' + i.license : '')) + '</span></li>').join('') + '</ul>' :
        '<p>No Commons photos have been loaded on this page yet.</p>') +
      '<p class="muted">Trip photos and the Ghana @ 70 clip are Curaters’ own.</p></div>';
    openDlg(dlg);
    $('.dlg-x', dlg).addEventListener('click', () => dlg.close());
  };

  /* ---------- lightbox ---------- */
  UI.lightbox = function (items, start, title) {
    let i = start || 0;
    const dlg = dialog('lb');
    dlg.innerHTML = '<button class="dlg-x" type="button" aria-label="Close"><svg class="ico"><use href="#i-x"/></svg></button>' +
      '<button class="lb-nav prev" type="button" aria-label="Previous photo"><svg class="ico"><use href="#i-chev"/></svg></button>' +
      '<figure><img alt=""><figcaption></figcaption></figure>' +
      '<button class="lb-nav next" type="button" aria-label="Next photo"><svg class="ico"><use href="#i-chev"/></svg></button>';
    const img = $('img', dlg), cap = $('figcaption', dlg);
    const show = (n) => { i = (n + items.length) % items.length; const it = items[i]; img.classList.remove('in'); img.alt = title || '';
      img.srcset = ''; img.src = P.url(it, 1920); img.onload = () => img.classList.add('in');
      cap.innerHTML = UI.esc(title || '') + ' <span>' + (i + 1) + ' / ' + items.length + '</span><small>' + UI.esc(P.credit(it)) + (it.page ? ' · <a href="' + UI.esc(it.page) + '" target="_blank" rel="noopener noreferrer">source</a>' : '') + '</small>'; };
    show(i); openDlg(dlg);
    $('.dlg-x', dlg).addEventListener('click', () => dlg.close());
    $('.prev', dlg).addEventListener('click', () => show(i - 1)); $('.next', dlg).addEventListener('click', () => show(i + 1));
    dlg.addEventListener('keydown', e => { if (e.key === 'ArrowLeft') show(i - 1); if (e.key === 'ArrowRight') show(i + 1); });
    let sx = null; dlg.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });
    dlg.addEventListener('touchend', e => { if (sx == null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 50) show(i + (dx < 0 ? 1 : -1)); sx = null; });
  };

  /* ---------- count-up numbers ---------- */
  UI.countUp = function (root) {
    const els = $$('[data-count]', root); if (!els.length) return;
    const run = (el) => { const end = +el.dataset.count; if (reduceMotion) { el.textContent = end; return; }
      const t0 = performance.now(); (function step(t) { const p = Math.min(1, (t - t0) / 1200); el.textContent = Math.round(end * (1 - Math.pow(1 - p, 3))); if (p < 1) requestAnimationFrame(step); })(t0); };
    if (!('IntersectionObserver' in window)) return els.forEach(run);
    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { run(e.target); io.unobserve(e.target); } }), { threshold: .6 });
    els.forEach(e => io.observe(e));
  };

  /* ---------- boot ---------- */
  function boot() {
    document.body.insertAdjacentHTML('afterbegin', L.sprite);
    const skip = document.createElement('a'); skip.className = 'skip'; skip.href = '#'; skip.addEventListener('click', e => { e.preventDefault(); const m = document.getElementById('main'); if (m) m.focus(); }); skip.textContent = 'Skip to content'; document.body.prepend(skip);
    const h = header(); skip.after(h);
    wireHeader(h);
    const slot = $('#site-footer'); const f = footer(); if (slot) slot.replaceWith(f); else document.body.appendChild(f);
    $('[data-credits]', f).addEventListener('click', UI.creditsDialog);

    document.body.insertAdjacentHTML('beforeend',
      '<div class="progress" aria-hidden="true"></div><button id="toTop" class="to-top" type="button" aria-label="Back to top"><svg class="ico" style="transform:rotate(-90deg)"><use href="#i-arrow"/></svg></button>' +
      '<a id="stickyCta" class="sticky-cta" href="#/plan">Request a trip ' + L.icon('arrow') + '</a>');
    $('#toTop').addEventListener('click', () => scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' }));

    pointerFx(); L.startClocks();
    UI.reveal(document); UI.countUp(document);
    document.addEventListener('curaters:unit', () => UI.hydrateWeather(document));
    setInterval(() => UI.hydrateWeather(document), 10 * 60 * 1000);
    C._ready = true;
    document.dispatchEvent(new CustomEvent('curaters:ready'));
  }
  C.ready = (fn) => (C._ready ? fn() : document.addEventListener('curaters:ready', fn, { once: true }));
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
})();

/* Curaters – home page behaviour */
Curaters.pages.home = function () {
  const C = Curaters, L = C.Live, P = C.Photos, UI = C.UI, $ = UI.$, $$ = UI.$$;
  const D = C.DESTINATIONS;
  const now = new Date();
  const curMonth = now.getMonth() + 1;

  /* ---------- HERO slideshow ---------- */
  const heroIds = ['serengeti', 'cape-coast-castle', 'kilimanjaro', 'zanzibar', 'sossusvlei', 'victoria-falls'];
  const heroD = heroIds.map(UI.dest);
  const slidesEl = $('#heroSlides'), dotsEl = $('#heroDots');
  const DUR = 7000;
  let cur = 0, timer = null, heroW = {}, credits = [];

  heroD.forEach((d, i) => {
    const s = document.createElement('div'); s.className = 'slide'; s.style.setProperty('--hue', d.hue);
    s.innerHTML = '<div class="ph"><img alt="" decoding="async"><div class="ph-fb"></div></div>';
    slidesEl.appendChild(s);
    const b = document.createElement('button'); b.type = 'button'; b.role = 'tab'; b.textContent = d.name.replace(/ &.*/, '').replace('Mount ', '').replace('Pyramids of ', '');
    b.style.setProperty('--dur', DUR + 'ms'); b.setAttribute('aria-label', 'Show ' + d.name);
    b.addEventListener('click', () => go(i, true));
    dotsEl.appendChild(b);
  });
  // load the first photo immediately, the rest shortly after
  heroD.forEach((d, i) => setTimeout(() => P.fill($('.ph', slidesEl.children[i]), d, {
    sizes: '100vw', w: 1920, onItem: it => { credits[i] = P.credit(it); if (i === cur) $('#hlCredit').textContent = credits[i]; }
  }), i === 0 ? 0 : 600 + i * 350));

  function paintLive() {
    if (!slidesEl.isConnected) return;
    const d = heroD[cur], w = heroW[d.id];
    $('#hlName').textContent = d.name;
    $('#hlLink').href = '#/destination?d=' + d.id;
    $('#hlTime').innerHTML = '<span data-clock="' + d.tz + '">' + L.time(d.tz) + '</span>';
    const c = w && w.current;
    if (c) { const k = L.describe(c.weather_code, c.is_day); $('#hlWx').innerHTML = L.icon(k.icon) + L.temp(c.temperature_2m); } else $('#hlWx').textContent = '–';
    const sun = L.sunInfo(w, d.tz);
    $('#hlSunK').textContent = sun ? sun.kind : 'Sun';
    $('#hlSun').textContent = sun ? sun.next : '–';
    $('#hlCredit').textContent = credits[cur] || '';
  }
  function go(i, user) {
    if (!slidesEl.isConnected) return;
    cur = (i + heroD.length) % heroD.length;
    $$('.slide', slidesEl).forEach((s, k) => s.classList.toggle('on', k === cur));
    $$('button', dotsEl).forEach((b, k) => { b.classList.remove('on'); b.setAttribute('aria-selected', k === cur); if (k === cur) { void b.offsetWidth; b.classList.add('on'); } });
    paintLive();
    clearTimeout(timer);
    if (!UI.reduceMotion || user) timer = setTimeout(() => go(cur + 1), DUR);
  }
  go(0);
  L.weather(heroD).then(w => { heroW = w; paintLive(); });
  document.addEventListener('curaters:unit', paintLive);
  document.addEventListener('visibilitychange', () => { if (document.hidden) clearTimeout(timer); else go(cur); });
  // swipe on touch
  let sx = null; const hero = $('#hero');
  hero.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });
  hero.addEventListener('touchend', e => { if (sx == null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 60) go(cur + (dx < 0 ? 1 : -1), true); sx = null; });
  // subtle pointer parallax on the headline
  if (matchMedia('(hover:hover) and (pointer:fine)').matches && !UI.reduceMotion) {
    const copy = $('.hero-copy');
    hero.addEventListener('pointermove', e => { const x = (e.clientX / innerWidth - .5), y = (e.clientY / innerHeight - .5);
      copy.style.transform = 'translate(' + (x * -14).toFixed(1) + 'px,' + (y * -10).toFixed(1) + 'px)'; slidesEl.style.transform = 'translate(' + (x * 10).toFixed(1) + 'px,' + (y * 8).toFixed(1) + 'px) scale(1.04)'; });
  }

  /* ---------- TICKER ---------- */
  const tk = $('#ticker');
  const tickHTML = D.map(d => '<a class="tick" href="#/destination?d=' + d.id + '"><b>' + UI.esc(d.name.split(' & ')[0]) + '</b><span class="c">' + UI.esc(d.country.split(' & ')[0]) + '</span><span class="t" data-clock="' + d.tz + '">' + L.time(d.tz) + '</span><span data-w="' + d.id + '" style="display:inline-flex;align-items:center;gap:6px"></span></a>').join('');
  tk.innerHTML = tickHTML + tickHTML;
  UI.hydrateWeather(tk);

  /* ---------- IN SEASON rail ---------- */
  $('#seasonEyebrow').textContent = 'In season · ' + UI.MONTHS[curMonth - 1] + ' ' + now.getFullYear();
  $('#seasonTitle').innerHTML = 'Where to go <em class="it">in ' + UI.MONTHS[curMonth - 1] + '</em>';
  const ranked = D.map((d, i) => ({ d, r: UI.rating(d, curMonth), i })).sort((a, b) => b.r - a.r || a.i - b.i);
  const rail = $('#rail');
  ranked.forEach((x, i) => { const c = UI.destCard(x.d); c.style.setProperty('--d', (i % 4) * 70 + 'ms'); rail.appendChild(c); });
  UI.reveal(rail); UI.hydrateWeather(rail);
  const prev = $('#railPrev'), next = $('#railNext');
  const step = () => Math.max(280, rail.clientWidth * .7);
  const sync = () => { prev.disabled = rail.scrollLeft < 8; next.disabled = rail.scrollLeft > rail.scrollWidth - rail.clientWidth - 8; };
  prev.addEventListener('click', () => rail.scrollBy({ left: -step(), behavior: 'smooth' }));
  next.addEventListener('click', () => rail.scrollBy({ left: step(), behavior: 'smooth' }));
  rail.addEventListener('scroll', sync, { passive: true }); sync(); addEventListener('resize', sync);
  rail.addEventListener('keydown', e => { if (e.key === 'ArrowRight') next.click(); if (e.key === 'ArrowLeft') prev.click(); });
  // mouse drag-to-scroll
  let down = false, sx0 = 0, sl0 = 0, moved = false;
  rail.addEventListener('pointerdown', e => { if (e.pointerType !== 'mouse') return; down = true; moved = false; sx0 = e.clientX; sl0 = rail.scrollLeft; });
  addEventListener('pointermove', e => { if (!down) return; const dx = e.clientX - sx0; if (Math.abs(dx) > 5) { moved = true; rail.classList.add('drag'); } if (moved) rail.scrollLeft = sl0 - dx; });
  addEventListener('pointerup', () => { if (!down) return; down = false; rail.classList.remove('drag'); });
  rail.addEventListener('click', e => { if (moved) { e.preventDefault(); e.stopPropagation(); moved = false; } }, true);

  /* ---------- MONTH PLANNER ---------- */
  const monthsEl = $('#months'), rows = $('#pickrows');
  let sel = curMonth;
  UI.MONTHS.forEach((m, i) => {
    const b = document.createElement('button'); b.type = 'button'; b.textContent = m.slice(0, 3); b.setAttribute('aria-pressed', i + 1 === sel);
    if (i + 1 === curMonth) { b.classList.add('now'); b.title = 'This month'; }
    b.addEventListener('click', () => { sel = i + 1; $$('button', monthsEl).forEach((x, k) => x.setAttribute('aria-pressed', k + 1 === sel)); renderRows(); });
    monthsEl.appendChild(b);
  });
  function renderRows() {
    const list = D.map((d, i) => ({ d, r: UI.rating(d, sel), i })).filter(x => x.r >= 2).sort((a, b) => b.r - a.r || a.i - b.i).slice(0, 6);
    rows.innerHTML = '';
    list.forEach((x, k) => {
      const a = document.createElement('a'); a.className = 'pickrow'; a.href = '#/destination?d=' + x.d.id; a.style.setProperty('--i', k); a.style.setProperty('--hue', x.d.hue);
      a.innerHTML = '<div class="th"><div class="ph"><img alt="" decoding="async"><div class="ph-fb"></div></div></div>' +
        '<div><h3>' + UI.esc(x.d.name) + '</h3><small>' + UI.esc(x.d.country) + ' · ' + UI.esc(x.d.duration) + '</small></div>' +
        '<span class="dots" aria-hidden="true">' + [0, 1, 2].map(n => '<i class="' + (n < x.r ? 'f' : '') + '"></i>').join('') + '</span>' +
        '<span class="tag s' + x.r + '">' + UI.RATE[x.r] + '</span>';
      rows.appendChild(a); P.lazy($('.ph', a), x.d, { w: 500, sizes: '56px' });
    });
    if (!list.length) rows.innerHTML = '<p class="lead" style="color:rgba(255,255,255,.7)">Nothing stands out in ' + UI.MONTHS[sel - 1] + '. Ask us for a bespoke suggestion.</p>';
  }
  renderRows();

  /* ---------- TRIP FORMATS ---------- */
  const tiles = $('#tiles');
  Object.entries(C.TRIP_TYPES).forEach(([k, t], i) => {
    const n = C.TRIPS.filter(x => x.type === k).length;
    const a = document.createElement('a'); a.className = 'tile reveal'; a.href = '#/trips?type=' + k;
    a.innerHTML = '<div><p class="n">0' + (i + 1) + (n ? ' · ' + n + ' available' : ' · by request') + '</p><h3>' + t.label.replace(' Trips', '') + '</h3><p>' + UI.esc(t.intro.split('. ')[0].replace(/\.$/, '') + '.') + '</p></div><span class="go">See ' + t.label.toLowerCase() + ' <svg class="ico"><use href="#i-arrow"/></svg></span>';
    tiles.appendChild(a);
  });
  UI.reveal(tiles);

  /* ---------- HOW IT WORKS ---------- */
  const stepsEl = $('#steps'), vis = $('#howVisual');
  const howD = ['maasai-mara', 'sossusvlei', 'zanzibar', 'serengeti'].map(UI.dest);
  howD.forEach((d, i) => { const ph = document.createElement('div'); ph.className = 'ph'; ph.style.cssText = 'transition:opacity 1s;opacity:' + (i ? 0 : 1); ph.style.setProperty('--hue', d.hue); ph.innerHTML = '<img alt="" decoding="async"><div class="ph-fb"></div>'; vis.prepend(ph); P.lazy(ph, d, { sizes: '50vw' }); });
  const layers = $$('.ph', vis).reverse();
  C.HOW.forEach((s, i) => {
    const el = document.createElement('div'); el.className = 'step' + (i === 0 ? ' open' : '');
    el.innerHTML = '<button type="button" aria-expanded="' + (i === 0) + '"><span class="num">' + (i + 1) + '</span><h3>' + UI.esc(s.t) + '</h3><svg class="ico"><use href="#i-chev"/></svg></button><div class="body"><div><p>' + UI.esc(s.d) + '</p></div></div>';
    $('button', el).addEventListener('click', () => open(i));
    stepsEl.appendChild(el);
  });
  function open(i) {
    $$('.step', stepsEl).forEach((s, k) => { s.classList.toggle('open', k === i); $('button', s).setAttribute('aria-expanded', k === i); });
    layers.forEach((l, k) => { l.style.opacity = k === i ? 1 : 0; });
    $('#howK').textContent = 'Step ' + (i + 1); $('#howT').textContent = C.HOW[i].t;
  }
  open(0);

  /* ---------- STATS ---------- */
  const countries = new Set(); D.forEach(d => d.country.split(' & ').forEach(c => countries.add(c)));
  const regions = new Set(D.map(d => d.region));
  $('#stats').innerHTML = [[D.length, 'Destinations'], [countries.size, 'Countries'], [regions.size, 'Regions'], [Object.keys(C.TRIP_TYPES).length, 'Ways to travel']]
    .map(([n, l]) => '<div class="stat"><b data-count="' + n + '">0</b><span>' + l + '</span></div>').join('');
  UI.countUp($('#stats'));

  /* ---------- CTA ---------- */
  const q = $('#quick');
  q.dest.innerHTML = '<option value="">Where to?</option>' + D.map(d => '<option value="' + d.id + '">' + UI.esc(d.name + ', ' + d.country) + '</option>').join('');
  q.month.innerHTML = UI.MONTHS.map((m, i) => '<option value="' + (i + 1) + '"' + (i + 1 === (curMonth % 12) + 1 ? ' selected' : '') + '>' + m + '</option>').join('');
  q.addEventListener('submit', e => { e.preventDefault(); const p = new URLSearchParams(); if (q.dest.value) p.set('dest', q.dest.value); p.set('month', q.month.value); p.set('n', q.n.value || 2); location.href = '#/plan?' + p; });
  const ctaD = UI.dest('victoria-falls'); P.lazy($('#ctaPh'), ctaD, { sizes: '100vw', w: 1280 });
  $('#ctaPh').style.setProperty('--hue', ctaD.hue);
};

/* Curaters – destinations explorer */
Curaters.pages.destinations = function () {
  const C = Curaters, L = C.Live, UI = C.UI, $ = UI.$, $$ = UI.$$;
  const D = C.DESTINATIONS;
  const grid = $('#grid'), count = $('#count');
  const cards = new Map(D.map((d, i) => [d.id, UI.destCard(d, { cls: 'pop' })]));
  const curMonth = new Date().getMonth() + 1;
  let weather = {};

  const state = { q: '', theme: '', region: '', sort: 'rec', view: 'grid', season: false };
  const sp = new URLSearchParams(Curaters.route.search);
  ['q', 'theme', 'region', 'sort', 'view'].forEach(k => { if (sp.get(k)) state[k] = sp.get(k); });
  state.season = sp.get('season') === '1';

  /* controls */
  const themes = $('#themes');
  [{ id: '', label: 'All' }].concat(C.THEMES).forEach(t => {
    const b = document.createElement('button'); b.type = 'button'; b.className = 'chip'; b.dataset.t = t.id; b.textContent = t.label;
    b.addEventListener('click', () => { state.theme = t.id; render(); });
    themes.appendChild(b);
  });
  const region = $('#region');
  Array.from(new Set(D.map(d => d.region))).forEach(r => region.insertAdjacentHTML('beforeend', '<option>' + r + '</option>'));
  $('#q').value = state.q; region.value = state.region; $('#sort').value = state.sort; $('#inSeason').checked = state.season;
  $('#q').addEventListener('input', e => { state.q = e.target.value.trim().toLowerCase(); render(); });
  region.addEventListener('change', e => { state.region = e.target.value; render(); });
  $('#sort').addEventListener('change', e => { state.sort = e.target.value; render(); });
  $('#inSeason').addEventListener('change', e => { state.season = e.target.checked; render(); });
  $$('.seg button').forEach(b => b.addEventListener('click', () => { state.view = b.dataset.view; render(false); }));
  if (state.q) $('#q').value = state.q;

  function matches(d) {
    if (state.theme && !d.tags.includes(state.theme)) return false;
    if (state.region && d.region !== state.region) return false;
    if (state.season && UI.rating(d, curMonth) < 2) return false;
    if (state.q) {
      const hay = (d.name + ' ' + d.country + ' ' + d.region + ' ' + d.tagline + ' ' + d.desc + ' ' + d.tags.join(' ')).toLowerCase();
      if (!state.q.split(/\s+/).every(w => hay.includes(w))) return false;
    }
    return true;
  }
  function sorted(list) {
    const idx = new Map(D.map((d, i) => [d.id, i]));
    if (state.sort === 'az') return list.sort((a, b) => a.name.localeCompare(b.name));
    if (state.sort === 'season') return list.sort((a, b) => UI.rating(b, curMonth) - UI.rating(a, curMonth) || idx.get(a.id) - idx.get(b.id));
    if (state.sort === 'warm') return list.sort((a, b) => ((weather[b.id] && weather[b.id].current.temperature_2m) ?? -99) - ((weather[a.id] && weather[a.id].current.temperature_2m) ?? -99));
    return list;
  }

  function render(animate) {
    $$('.chip', themes).forEach(b => b.setAttribute('aria-pressed', b.dataset.t === state.theme));
    $$('.seg button').forEach(b => b.setAttribute('aria-pressed', b.dataset.view === state.view));
    grid.dataset.view = state.view;
    const list = sorted(D.filter(matches));
    count.textContent = list.length + (list.length === 1 ? ' destination' : ' destinations');
    if (!list.length) {
      grid.innerHTML = '<div class="empty"><h3>No matches yet</h3><p>Try a different search or clear the filters. Or tell us your idea and we will design it.</p><p style="margin-top:18px"><a class="btn btn-dark btn-sm" href="#/plan">Request a trip</a></p></div>';
    } else {
      const els = list.map((d, k) => { const c = cards.get(d.id); c.style.setProperty('--k', Math.min(k, 8)); c.classList.remove('pop'); if (animate !== false) { void c.offsetWidth; c.classList.add('pop'); } c.classList.add('in'); return c; });
      grid.replaceChildren(...els);
    }
    // keep URL shareable
    const p = new URLSearchParams();
    if (state.q) p.set('q', state.q); if (state.theme) p.set('theme', state.theme); if (state.region) p.set('region', state.region);
    if (state.sort !== 'rec') p.set('sort', state.sort); if (state.view !== 'grid') p.set('view', state.view); if (state.season) p.set('season', '1');
    history.replaceState(null, '', '#/destinations' + (p.toString() ? '?' + p : ''));
  }

  render();
  async function refresh() {
    if (!grid.isConnected) return;
    weather = await L.weather(D);
    const got = Object.values(weather).filter(Boolean).length;
    $('#upd').textContent = got ? 'Live weather updated ' + L.time(Intl.DateTimeFormat().resolvedOptions().timeZone) + ' · refreshes every 10 min' : 'Live weather unavailable right now. Showing cached or offline data.';
    UI.hydrateWeather(grid);
    if (state.sort === 'warm') render(false);
  }
  refresh(); setInterval(refresh, 10 * 60 * 1000);
};

/* Curaters – single destination page */
Curaters.pages.destination = function () {
  const C = Curaters, L = C.Live, P = C.Photos, UI = C.UI, $ = UI.$, $$ = UI.$$;
  const d = UI.dest(UI.param('d')) || UI.dest('serengeti');
  const curMonth = new Date().getMonth() + 1;
  document.title = d.name + ' | Curaters';
  document.querySelector('meta[name="description"]').content = d.name + ', ' + d.country + '. ' + d.tagline + ' Live weather, local time and best months to visit.';
  $('#crumb').textContent = d.name;
  $('#dEyebrow').textContent = d.region + ' · ' + d.country;
  $('#dName').textContent = d.name;
  $('#dTag').textContent = d.tagline;
  $('#dH2').textContent = d.tagline;
  $('#dDesc').textContent = d.desc;
  $('#dHl').innerHTML = d.highlights.map(h => '<li class="reveal">' + UI.esc(h) + '</li>').join('');
  $('#facts').innerHTML = Object.entries(d.facts).map(([k, v]) => '<div><dt>' + UI.esc(k) + '</dt><dd>' + UI.esc(v) + '</dd></div>').join('') + '<div><dt>Time zone</dt><dd>' + UI.esc(d.tz.split('/')[1].replace(/_/g, ' ')) + ' · ' + L.offset(d.tz) + '</dd></div>';
  $('#dPlan').href = '#/plan?dest=' + d.id + '&month=' + curMonth;
  $('#dhero').style.setProperty('--hue', d.hue);

  /* wishlist */
  const wb = $('#dWish');
  const syncW = () => wb.setAttribute('aria-pressed', String(C.Wish.has(d.id)));
  syncW(); wb.addEventListener('click', () => { const on = C.Wish.toggle(d.id); UI.toast(on ? d.name + ' added to your trip' : d.name + ' removed'); });
  document.addEventListener('curaters:wish', syncW);

  /* best months + live advice */
  const mEl = $('#months');
  mEl.innerHTML = UI.monthBars(d, curMonth);
  const r = UI.rating(d, curMonth);
  const adv = $('#dAdvice');
  adv.textContent = UI.MONTHS[curMonth - 1] + ' is ' + UI.RATE[r].toLowerCase() + ' for ' + d.name + (r >= 2 ? '. A great time to go.' : r === 1 ? '. Possible, with some trade-offs.' : '. Not ideal; ask us about better months.');
  adv.classList.toggle('good', r >= 2);

  /* photos: hero slideshow + gallery */
  const slides = $('#dslides'), thumbs = $('#dThumbs'), credit = $('#dCredit');
  let items = [], idx = 0, timer;
  P.get(d).then(list => {
    items = list.slice(0, 6);
    if (!items.length) { slides.innerHTML = '<div class="ph is-fallback" style="--hue:' + d.hue + '"><div class="ph-fb"><span>' + UI.esc(d.name) + '</span></div></div>'; credit.textContent = 'Photographs unavailable offline'; renderGallery([]); return; }
    items.forEach((it, i) => {
      const s = document.createElement('div'); s.className = 'slide' + (i === 0 ? ' on' : '');
      s.innerHTML = '<div class="ph is-loading" style="--hue:' + d.hue + '"><img alt="' + UI.esc(d.name + ', ' + d.country) + '" decoding="async"' + (i ? ' loading="lazy"' : ' fetchpriority="high"') + '></div>';
      const img = $('img', s), ph = $('.ph', s);
      img.sizes = '100vw'; if (it.srcset !== undefined) {}
      img.srcset = P.srcset(it); img.src = P.url(it, 1280);
      img.addEventListener('load', () => { ph.classList.remove('is-loading'); ph.classList.add('is-ready'); });
      img.addEventListener('error', () => { ph.classList.remove('is-loading'); ph.classList.add('is-fallback'); });
      slides.appendChild(s);
      const b = document.createElement('button'); b.type = 'button'; b.setAttribute('aria-label', 'Photo ' + (i + 1));
      b.innerHTML = '<img alt="" loading="lazy" src="' + P.url(it, 500) + '">'; b.addEventListener('click', () => { show(i); restart(); });
      if (items.length > 1) thumbs.appendChild(b);
    });
    show(0); restart();
    renderGallery(list);
  });
  function show(i) {
    idx = i; $$('.slide', slides).forEach((s, k) => s.classList.toggle('on', k === i));
    $$('button', thumbs).forEach((b, k) => b.classList.toggle('on', k === i));
    credit.textContent = P.credit(items[i]);
  }
  function restart() { clearInterval(timer); if (items.length > 1 && !UI.reduceMotion) timer = setInterval(() => { if (!slides.isConnected) return clearInterval(timer); show((idx + 1) % items.length); }, 7000); }
  function renderGallery(list) {
    const g = $('#gallery');
    if (!list.length) { g.innerHTML = '<p class="muted">Photographs will appear here when you are online.</p>'; g.style.display = 'block'; return; }
    list.slice(0, 10).forEach((it, i) => {
      const b = document.createElement('button'); b.type = 'button'; b.setAttribute('aria-label', 'Open photo ' + (i + 1) + ' of ' + d.name);
      b.innerHTML = '<img alt="' + UI.esc(it.alt || d.name) + '" loading="lazy" decoding="async">';
      const img = $('img', b); img.srcset = P.srcset(it); img.sizes = i % 5 === 0 ? '(max-width:900px) 100vw, 40vw' : '(max-width:900px) 50vw, 20vw'; img.src = P.url(it, 500);
      img.addEventListener('load', () => img.classList.add('in'));
      b.addEventListener('click', () => UI.lightbox(list.slice(0, 10), i, d.name));
      g.appendChild(b);
    });
  }

  /* live panel + forecast */
  let w = null, fx = null;
  function paint() {
    if (!slides.isConnected) return;
    $('#live').innerHTML = UI.liveFull(d, w, fx);
    $('#fc').innerHTML = w ? UI.forecast(w, d.tz, 7) + '<p class="muted" style="margin-top:10px;font-size:.74rem">Blue % = chance of precipitation. Source: Open-Meteo.</p>' : '<p class="muted">Forecast unavailable offline.</p>';
    L.startClocks();
  }
  async function refresh() { const res = await Promise.all([L.weather([d]), L.rates()]); w = res[0][d.id]; fx = res[1]; paint(); }
  paint(); refresh(); setInterval(refresh, 10 * 60 * 1000);
  document.addEventListener('curaters:unit', paint);

  /* related: same theme/region, nearest in the list */
  const rel = C.DESTINATIONS.filter(x => x.id !== d.id).map(x => ({ x, s: x.tags.filter(t => d.tags.includes(t)).length * 2 + (x.region === d.region ? 1 : 0) + UI.rating(x, curMonth) * .3 })).sort((a, b) => b.s - a.s).slice(0, 3);
  const relEl = $('#related'); rel.forEach(o => relEl.appendChild(UI.destCard(o.x)));
  UI.reveal(relEl); UI.hydrateWeather(relEl);
};

/* Curaters – trips page */
Curaters.pages.trips = function () {
  const C = Curaters, L = C.Live, P = C.Photos, UI = C.UI, $ = UI.$, $$ = UI.$$;
  const types = Object.keys(C.TRIP_TYPES);
  let type = types.includes(UI.param('type')) ? UI.param('type') : 'day';
  let cur = 'USD'; try { cur = localStorage.getItem('curaters.cur') || 'USD'; } catch (e) {}

  const tabs = $('#tabs'), ind = $('#ind'), grid = $('#tgrid');
  types.forEach(t => {
    const b = document.createElement('button'); b.type = 'button'; b.role = 'tab'; b.dataset.t = t;
    b.textContent = C.TRIP_TYPES[t].label; b.addEventListener('click', () => select(t, true));
    b.addEventListener('keydown', e => { const i = types.indexOf(type); if (e.key === 'ArrowRight') select(types[(i + 1) % 4], true, true); if (e.key === 'ArrowLeft') select(types[(i + 3) % 4], true, true); });
    tabs.appendChild(b);
  });
  function moveInd() { const b = $('button[aria-selected="true"]', tabs); if (!b) return; ind.style.width = b.offsetWidth + 'px'; ind.style.transform = 'translateX(' + (b.offsetLeft - 5) + 'px)'; b.scrollIntoView({ block: 'nearest', inline: 'center' }); }
  addEventListener('resize', moveInd);

  /* currency */
  const curEl = $('#cur');
  ['USD', 'GHS', 'EUR', 'GBP'].forEach(c => {
    const b = document.createElement('button'); b.type = 'button'; b.textContent = c; b.dataset.c = c;
    b.addEventListener('click', () => { cur = c; try { localStorage.setItem('curaters.cur', c); } catch (e) {} paintCur(); render(false); });
    curEl.appendChild(b);
  });
  function paintCur() { $$('button', curEl).forEach(b => b.setAttribute('aria-pressed', b.dataset.c === cur)); }
  paintCur();
  L.rates().then(fx => {
    $('#fxNote').textContent = fx ? 'Live rates · 1 USD = ' + fx.rates.GHS.toFixed(2) + ' GHS · ' + fx.rates.EUR.toFixed(3) + ' EUR · ' + fx.rates.GBP.toFixed(3) + ' GBP' : 'Live rates unavailable, showing USD';
    render(false);
  });

  const price = (t) => t.price <= 5 ? '<span class="price" style="font-size:1.15rem">Price on request</span>' : '<span class="price">' + L.money(t.price, cur) + (cur !== 'USD' ? ' <small>≈ $' + t.price.toLocaleString('en-US') + '</small>' : ' <small>per person</small>') + '</span>';

  function card(t, i) {
    const d = UI.dest(t.dest);
    const el = document.createElement('article'); el.className = 'tcard reveal in'; el.style.animation = 'pop .6s var(--ease) both'; el.style.animationDelay = i * 70 + 'ms';
    const people = t.slots ? t.slots + ' slots' : t.min + ' – ' + t.max + ' travellers';
    const meter = t.slots ? Math.min(100, Math.max(6, 100 - Math.min(t.slots, 100))) : Math.round((t.min / t.max) * 100);
    el.innerHTML =
      '<div class="tmedia"><img src="' + t.image + '" alt="' + UI.esc(t.title + ', ' + t.place) + '" loading="lazy" decoding="async">' +
      (t.video ? '<video muted loop playsinline preload="none" poster="' + t.image + '" src="' + t.video + '" aria-hidden="true"></video><span class="vid-hint"><svg class="ico" viewBox="0 0 24 24" fill="currentColor" style="width:12px;height:12px"><path d="M8 5v14l11-7z"/></svg> Clip from Cape Coast Castle</span>' : '') +
      '<div class="badges"><span class="badge">' + C.TRIP_TYPES[t.type].label.replace(' Trips', '') + '</span>' + (t.status === 'pending' ? '<span class="badge warn">Pending</span>' : '<span class="badge soft">' + people + '</span>') + '</div></div>' +
      '<div class="tbody"><p class="place">' + L.icon('pin') + UI.esc(t.place) + '</p><h3>' + UI.esc(t.title) + '</h3><p class="blurb">' + UI.esc(t.blurb) + '</p>' +
      (t.status === 'pending' ? '' : '<div class="meter" aria-hidden="true"><i style="--w:' + meter + '%"></i></div>') +
      '<div class="tmeta"><span>' + (t.status === 'pending' ? people : (t.slots ? 'Limited capacity' : 'Small group')) + '</span><span data-clock="' + d.tz + '" title="Local time"></span></div>' +
      '<div class="tmeta" style="align-items:center">' + price(t) + '<a href="#/destination?d=' + d.id + '" class="link-btn" style="font-size:.8rem">Destination guide</a></div>' +
      '<a class="btn btn-dark" href="#/plan?trip=' + t.id + '">' + (t.status === 'pending' ? 'Join the waitlist' : 'Request this trip') + ' <svg class="ico"><use href="#i-arrow"/></svg></a></div>';
    // local clock label
    const clk = $('[data-clock]', el); clk.textContent = L.time(d.tz) + ' local';
    clk.removeAttribute('data-clock'); clk.dataset.tzlabel = d.tz;
    // video: hover on desktop, in-view on touch
    const v = $('video', el);
    if (v) {
      const play = () => { el.classList.add('playing'); v.play().catch(() => {}); }, stop = () => { el.classList.remove('playing'); v.pause(); };
      if (matchMedia('(hover:hover)').matches) { el.addEventListener('pointerenter', play); el.addEventListener('pointerleave', stop); el.addEventListener('focusin', play); el.addEventListener('focusout', stop); }
      else if ('IntersectionObserver' in window && !UI.reduceMotion) new IntersectionObserver(es => es.forEach(e => e.isIntersecting ? play() : stop()), { threshold: .7 }).observe(el);
    }
    return el;
  }

  function render(animate) {
    grid.replaceChildren();
    const meta = C.TRIP_TYPES[type];
    $('#tTitle').textContent = meta.label; $('#tIntro').textContent = meta.intro;
    document.title = meta.label + ' | Curaters';
    $$('button', tabs).forEach(b => b.setAttribute('aria-selected', b.dataset.t === type));
    moveInd();
    const list = C.TRIPS.filter(t => t.type === type);
    if (type === 'private') {
      const div = document.createElement('div'); div.className = 'private-card reveal in';
      div.innerHTML = '<div class="l"><p class="eyebrow" style="color:var(--terra-l)">By invitation</p><h3>Journeys made <em class="it" style="color:var(--terra-l)">only for you</em></h3><p>Private trips are designed one at a time, around your interests, pace and travel style. Tell us about it and we will reply personally.</p>' +
        '<ul><li>Itinerary designed from scratch with you</li><li>Your own guides, drivers and stays, chosen with care</li><li>Flexible dates and the privacy to go at your pace</li></ul>' +
        '<a class="btn btn-primary" href="#/plan?type=private">Request private access <svg class="ico"><use href="#i-arrow"/></svg></a></div><div class="r"><div class="ph" style="--hue:30"><img alt="" decoding="async"><div class="ph-fb"></div></div></div>';
      grid.appendChild(div);
      const dd = UI.dest('serengeti'); P.lazy($('.ph', div), dd, { sizes: '50vw', w: 1280 });
      return;
    }
    if (!list.length) { grid.innerHTML = '<div class="empty t-empty"><h3>No ' + meta.label.toLowerCase() + ' open right now</h3><p>New dates are added regularly. Tell us what you are looking for.</p><p style="margin-top:18px"><a class="btn btn-dark btn-sm" href="#/plan">Request a trip</a></p></div>'; return; }
    list.forEach((t, i) => grid.appendChild(card(t, animate === false ? 0 : i)));
  }

  function select(t, user, focus) {
    type = t;
    if (user) { const p = new URLSearchParams(Curaters.route.search); p.set('type', t); history.replaceState(null, '', '#/trips?' + p); }
    render(); if (focus) $('button[aria-selected="true"]', tabs).focus();
  }
  // keep any trip clocks ticking
  setInterval(() => $$('[data-tzlabel]').forEach(e => { e.textContent = L.time(e.dataset.tzlabel) + ' local'; }), 15000);
  render();
};

/* Curaters – trip request planner */
Curaters.pages.plan = function () {
  const C = Curaters, L = C.Live, P = C.Photos, UI = C.UI, $ = UI.$, $$ = UI.$$;
  const D = C.DESTINATIONS, now = new Date();
  const sp = new URLSearchParams(Curaters.route.search);
  const trip = C.TRIPS.find(t => String(t.id) === sp.get('trip'));
  const sel = new Set(C.Wish.list().filter(id => UI.dest(id)));
  if (UI.dest(sp.get('dest'))) sel.add(sp.get('dest'));
  if (trip && UI.dest(trip.dest)) sel.add(trip.dest);
  let month = +sp.get('month') || (now.getMonth() + 1) % 12 + 1;
  let n = Math.min(30, Math.max(1, +sp.get('n') || (trip && trip.min) || 2));
  let style = trip ? trip.type : (['day', 'private', 'group', 'hosted'].includes(sp.get('type')) ? sp.get('type') : 'private');
  let step = 0, cur = 'USD';
  const steps = ['Where', 'When & who', 'You'];

  /* stepper */
  const st = $('#stepper');
  steps.forEach((s, i) => { const b = document.createElement('button'); b.type = 'button'; b.innerHTML = '<div class="bar"></div><span>' + (i + 1) + '. ' + s + '</span>'; b.addEventListener('click', () => { if (i <= step || valid(step)) go(i); }); st.appendChild(b); });
  function go(i) {
    step = i;
    $$('.fstep').forEach(s => s.classList.toggle('on', +s.dataset.step === i));
    $$('button', st).forEach((b, k) => { b.classList.toggle('on', k === i); b.classList.toggle('done', k < i); });
    st.hidden = i > 2;
    const t = $('.fstep.on'); if (t && i < 3) scrollTo({ top: Math.max(0, $('.plan').offsetTop - 100), behavior: UI.reduceMotion ? 'auto' : 'smooth' });
  }
  function valid(i) {
    if (i !== 2) return true;
    let ok = true;
    [['#fname', v => v.trim().length > 1, 'Please enter your name'], ['#femail', v => /^\S+@\S+\.\S+$/.test(v), 'Please enter a valid email']].forEach(([s, f, m]) => {
      const el = $(s); const good = f(el.value); el.setAttribute('aria-invalid', !good); el.parentNode.querySelector('.err').textContent = good ? '' : m; if (!good) ok = false; });
    return ok;
  }
  $$('[data-next]').forEach(b => b.addEventListener('click', () => go(Math.min(2, step + 1))));
  $$('[data-prev]').forEach(b => b.addEventListener('click', () => go(Math.max(0, step - 1))));

  /* destination picks */
  const picks = $('#picks');
  D.forEach(d => {
    const b = document.createElement('button'); b.type = 'button'; b.className = 'pick'; b.style.setProperty('--hue', d.hue);
    b.innerHTML = '<div class="ph"><img alt="" decoding="async"><div class="ph-fb"></div></div><i class="tick-mark"></i><span>' + UI.esc(d.name) + '<small>' + UI.esc(d.country) + '</small></span>';
    b.setAttribute('aria-pressed', sel.has(d.id));
    b.addEventListener('click', () => { sel.has(d.id) ? sel.delete(d.id) : sel.add(d.id); b.setAttribute('aria-pressed', sel.has(d.id)); paint(); });
    picks.appendChild(b); P.lazy($('.ph', b), d, { w: 500, sizes: '200px' });
  });

  /* months */
  const mg = $('#monthgrid');
  UI.MONTHS.forEach((m, i) => { const b = document.createElement('button'); b.type = 'button'; b.textContent = m.slice(0, 3); b.innerHTML += '<i></i>';
    b.addEventListener('click', () => { month = i + 1; paint(); }); mg.appendChild(b); });
  const fit = (m, list) => list.length ? Math.min.apply(null, list.map(d => UI.rating(d, m))) : -1;

  /* styles */
  $('#styles').innerHTML = Object.entries(C.TRIP_TYPES).map(([k, t]) => '<label><input type="radio" name="style" value="' + k + '"><span>' + t.label.replace(' Trips', '') + '</span></label>').join('');
  $$('#styles input').forEach(r => r.addEventListener('change', () => { style = r.value; paint(); }));

  $('#nMinus').addEventListener('click', () => { n = Math.max(1, n - 1); paint(); });
  $('#nPlus').addEventListener('click', () => { n = Math.min(30, n + 1); paint(); });
  $('#nights').addEventListener('input', paint); $('#budget').addEventListener('input', paint);

  function paint() {
    const list = Array.from(sel).map(UI.dest);
    $$('.pick', picks).forEach((b, i) => b.setAttribute('aria-pressed', sel.has(D[i].id)));
    $$('button', mg).forEach((b, i) => { b.setAttribute('aria-pressed', i + 1 === month); b.dataset.fit = list.length ? Math.min.apply(null, list.map(d => UI.rating(d, i + 1))) : ''; });
    $$('#styles input').forEach(r => { r.checked = r.value === style; });
    $('#nOut').textContent = n;
    const nights = +$('#nights').value, budget = +$('#budget').value;
    $('#nightsOut').textContent = nights; $('#budgetOut').textContent = '$' + budget.toLocaleString('en-US');
    const f = fit(month, list), a = $('#fit');
    if (f < 0) a.hidden = true; else {
      a.hidden = false; a.className = 'advice' + (f >= 2 ? ' good' : '');
      const bad = list.filter(d => UI.rating(d, month) <= 1).map(d => d.name);
      a.textContent = f >= 2 ? UI.MONTHS[month - 1] + ' suits all of your chosen places.' : UI.MONTHS[month - 1] + ' is a trade-off for ' + bad.join(', ') + '. Another month may be better; tell us your flexibility.';
    }
    $('#sumList').innerHTML = list.length ? list.map(d => '<div class="sum-item"><div>' + UI.esc(d.name) + '<small>' + UI.esc(d.country) + ' · <span data-clock="' + d.tz + '">' + L.time(d.tz) + '</span> local</small></div><button type="button" data-rm="' + d.id + '" aria-label="Remove ' + UI.esc(d.name) + '">&times;</button></div>').join('') : '<p class="muted">No destinations yet. We can suggest some.</p>';
    $$('[data-rm]').forEach(b => b.addEventListener('click', () => { sel.delete(b.dataset.rm); paint(); }));
    $('#sumMonth').textContent = UI.MONTHS[month - 1]; $('#sumN').textContent = n; $('#sumNights').textContent = nights + ' nights';
    $('#sumBudget').textContent = L.money(budget, cur) + ' pp'; $('#sumClocks').textContent = '';
    $('#budgetFx').textContent = cur !== 'USD' ? '≈ ' + L.money(budget, cur) : '';
    L.startClocks();
  }
  L.rates().then(fx => { if (fx && fx.rates && fx.rates.GHS) { cur = 'GHS'; try { const c = localStorage.getItem('curaters.cur'); if (c) cur = c; } catch (e) {} } paint(); });
  go(0); paint();

  /* submit */
  $('#planForm').addEventListener('submit', async e => {
    e.preventDefault();
    if (!valid(2)) return;
    const list = Array.from(sel).map(id => UI.dest(id).name);
    const data = { name: $('#fname').value.trim(), email: $('#femail').value.trim(), phone: $('#fphone').value.trim(), notes: $('#fnotes').value.trim(),
      destinations: list, month: UI.MONTHS[month - 1], travellers: n, nights: +$('#nights').value, budgetUSDperPerson: +$('#budget').value, style, trip: trip ? trip.title : '' };
    $('#doneName').textContent = data.name.split(' ')[0];
    const ep = C.CONFIG && C.CONFIG.formEndpoint;
    if (ep) {
      try { const r = await fetch(ep, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(data) }); if (!r.ok) throw 0;
        $('#doneMsg').textContent = 'Your request is with us. We will reply to ' + data.email + ' soon.'; go(3); return; } catch (err) { UI.toast('Could not send online. Opening your email app instead.'); }
    }
    const body = Object.entries({ Name: data.name, Email: data.email, Phone: data.phone, Destinations: list.join(', ') || 'Not sure yet', Month: data.month, Travellers: n, Nights: data.nights, 'Budget per person (USD)': data.budgetUSDperPerson, Style: style, Trip: data.trip, Notes: data.notes }).filter(x => x[1] !== '').map(x => x[0] + ': ' + x[1]).join('\n');
    location.href = 'mailto:' + C.CONTACT.email + '?subject=' + encodeURIComponent('Trip request: ' + (list[0] || 'Africa')) + '&body=' + encodeURIComponent(body);
    $('#doneMsg').textContent = 'Your email app should now open with the details filled in. Just press send. If it did not, write to ' + C.CONTACT.email + '.';
    go(3);
  });
};

Curaters.pages.about = function () {
  const C = Curaters, UI = C.UI;
  document.getElementById('faqList').innerHTML = C.FAQ.map(f => '<details><summary>' + UI.esc(f[0]) + '</summary><p>' + UI.esc(f[1]) + '</p></details>').join('');
  const e = document.getElementById('cEmail'); e.href = 'mailto:' + C.CONTACT.email; e.querySelector('b').textContent = C.CONTACT.email;
  document.getElementById('cIg').href = C.CONTACT.instagram; document.getElementById('cTt').href = C.CONTACT.tiktok;
};

/* =========================================================
   Router: one page, hash routes (#/destinations, #/trips?type=group ...)
   ========================================================= */
(function () {
  const C = Curaters, UI = C.UI, L = C.Live;
  const NAMES = { '': 'home', home: 'home', destinations: 'destinations', destination: 'destination', trips: 'trips', plan: 'plan', about: 'about' };
  const TITLES = { home: 'Curaters | Curated African Travel Experiences', destinations: 'Destinations | Curaters', trips: 'Trips | Curaters', plan: 'Plan a trip | Curaters', about: 'About | Curaters', notfound: 'Page not found | Curaters' };
  const OVERLAY = { home: 1, destination: 1 };
  function parse() {
    const h = location.hash.replace(/^#\/?/, ''); const i = h.indexOf('?');
    const path = (i < 0 ? h : h.slice(0, i)).replace(/\/$/, '');
    return { name: Object.prototype.hasOwnProperty.call(NAMES, path) ? NAMES[path] : 'notfound', search: i < 0 ? '' : '?' + h.slice(i + 1) };
  }
  let last = null;
  function mount() {
    const r = parse(); C.route = r;
    const main = document.getElementById('main');
    const t = document.getElementById('t-' + r.name);
    main.innerHTML = ''; main.appendChild(t.content.cloneNode(true));
    document.body.dataset.page = r.name; document.body.dataset.header = OVERLAY[r.name] ? 'overlay' : '';
    document.title = TITLES[r.name] || TITLES.notfound;
    document.querySelectorAll('.site-header nav a').forEach(a => {
      const on = a.getAttribute('href') === '#/' + r.name; if (on) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
    });
    const m = document.getElementById('mnav'); if (m) { m.hidden = true; document.body.classList.remove('menu-open'); const b = document.querySelector('.burger'); if (b) b.setAttribute('aria-expanded', 'false'); }
    if (C.pages[r.name]) C.pages[r.name]();
    UI.reveal(main); UI.countUp(main); L.startClocks();
    const key = r.name; if (last !== key || !/^#\/(destinations|trips)/.test(location.hash)) scrollTo(0, 0); last = key;
    dispatchEvent(new Event('scroll'));
  }
  window.addEventListener('hashchange', mount);
  C.ready(mount);
})();
